import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.CFuv5BrO.js";const h=JSON.parse('{"title":"Frequently Asked Questions","description":"How Hearth relates to coding agents, Codex, connectivity, Phase 1, external effects, self-evolution, and multi-user use.","frontmatter":{"title":"Frequently Asked Questions","description":"How Hearth relates to coding agents, Codex, connectivity, Phase 1, external effects, self-evolution, and multi-user use.","outline":false},"headers":[],"relativePath":"en/reference/faq.md","filePath":"en/reference/faq.md","lastUpdated":1794305977000}'),o={name:"en/reference/faq.md"};function s(i,e,l,d,c,u){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><p class="lead">These are the questions most likely to come up on first contact with Hearth. See the [overall design](/en/design/) for product boundaries and the [delivery route](/en/delivery/) for phase order.</p><p><strong>Is Hearth another coding agent?</strong> No. Codex is an important executor, but Hearth&#39;s product center is task control, durable execution, approval, receipts, memory, and verification. It is meant for broader personal digital work including email, calendars, documents, the web, desktops, and data.</p><p><strong>Is it a Codex wrapper?</strong> No. Hearth does not let Codex hold long-lived credentials, become the memory center, or expand its own authority. Codex receives minimal context, works in an isolated workspace, and returns artifacts and structured results. External actions still go through Hearth&#39;s approval, execution, and reconciliation.</p><p><strong>Does it require an internet connection?</strong> Local-first by default. Tasks, artifacts, memory, and credentials stay in an environment the user controls. Models, remote execution, and sync services are optional. When cloud capability is used, Hearth explains which data leaves the device, how long it is retained, and how it can be deleted.</p><p><strong>What can Phase 1 do?</strong> Phase 1 delivers the smallest complete MVP. It starts from 15 cross-industry real tasks and passes at least 10 of them while covering the full path in a real browser: create, execute, approve, inspect artifacts, and recover from failure. Phase 1 itself did not include sending email, writing calendars, desktop operation, proactive loops, full memory, or multiple devices; later phases formed code loops for these capabilities, but real accounts, real devices, and long-running acceptance remain incomplete.</p><p><strong>Why not build one universal agent?</strong> Because &quot;universal&quot; usually means permission, context, and failure boundaries are all uncontrolled. Hearth uses multiple specialized executors and chooses a path by capability, risk, reversibility, and cost. Each executor has explicit boundaries, verification, and human takeover.</p><p><strong>How are external actions prevented from repeating?</strong> Every external action records pending intent, receives preview and authorization, executes under the same identity, and saves a receipt. A retry does not create a second email or record. When an external system returns an uncertain result, Hearth reconciles first and stops for the user if it cannot confirm what happened.</p><p><strong>Will Hearth modify itself automatically?</strong> Not without bounds. Hearth can propose new methods from real traces, but a candidate must pass permission checks, replay, side-effect-free trials, limited real use, and rollback verification. The model cannot change authorization rules, approval thresholds, or core safety boundaries.</p><p><strong>Does it support multiple users, enterprises, and mobile?</strong> Hearth is a single-user, self-hosted product. Enterprise multi-tenancy, organizational audit, and billing are not first-version goals. Mobile is a controlled entry focused on review, approval, takeover, simple starts, and notifications; it does not duplicate every desktop management feature. A PWA shell, mobile bottom navigation, and Feishu text approval exist, but phone pairing, system-level push, remote takeover, and real-device installation remain unaccepted.</p><p>To continue, read the <a href="/hearth-os/en/design/">overall design</a> and the <a href="/hearth-os/en/delivery/">delivery route</a>. For implementation or maintenance details, use the other appendix pages.</p>',11)])])}const m=t(o,[["render",s]]);export{h as __pageData,m as default};
